/**
 * Generate tests/fixtures/engine-golden.json from DuckDB.
 *
 * Why a committed fixture rather than querying DuckDB in the test run: the
 * assertion "TsEngine === DuckDB" has to hold on every `pnpm test`, including CI
 * with no network and no wasm. Committing DuckDB's answers once, generated by
 * this script, turns a heavyweight dependency into a static file while keeping
 * the comparison honest — the fixture is produced by the same SQL the app runs.
 *
 * Method: the Node BLOCKING bundle (@duckdb/duckdb-wasm/blocking), one attempt,
 * no browser. If that ever fails the fallback is a Playwright harness under
 * scripts/e2e/; it is not implemented here because the blocking path works.
 *
 * Grid: the documented 3 scenario points, plus min / max / midpoint for each
 * slider, crossed over strength x jet x agri — 216 combinations (>= 200 required),
 * plus one full 918-row timeline.
 *
 *   pnpm gen:golden
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const CSV_PATH = path.join(root, 'public', 'data', 'enso.csv');
const OUT_PATH = path.join(root, 'tests', 'fixtures', 'engine-golden.json');

// --- the SQL, copied verbatim from src/lib/duckdb.ts ------------------------
// Kept as literals rather than imported so this script has no dependency on the
// TS build. If a query changes there, it must change here, and regenerating the
// fixture then makes TsEngine's failing test point at the real drift.

const SCENARIO_SQL = `
WITH params AS (
  SELECT
    CAST(? AS DOUBLE) AS sst,
    CAST(? AS DOUBLE) AS jet,
    CAST(? AS DOUBLE) AS agri
),
base AS (
  SELECT
    sst, jet, agri,
    sst * 1.15                              AS pacific_sst_dev,
    least(100.0, sst * 35.0)                AS pacific_convection,
    (15.0 + sst * 18.0)                     AS us_precip_base,
    (15.0 + sst * 18.0) + jet * 12.0        AS us_precip,
    (-0.5 - sst * 0.8) - jet * 0.6          AS us_temp_dev_f,
    (-10.0 - sst * 22.0) - jet * 9.0        AS asia_precip,
    least(10.0, greatest(0.0, sst * 3.2 * (1.0 + jet * 0.15))) AS asia_drought,
    (20.0 + sst * 25.0) + jet * -4.0        AS africa_precip,
    least(10.0, greatest(0.0, sst * 2.8))   AS africa_flood
  FROM params
)
SELECT
  round(sst, 2)                AS sst,
  round(jet, 2)                AS jet,
  round(agri, 2)               AS agri,
  round(pacific_sst_dev, 2)    AS pacific_sst_dev,
  round(pacific_convection, 1) AS pacific_convection,
  round(us_precip, 1)          AS us_precip,
  round(us_precip_base, 1)     AS us_precip_base,
  round(us_temp_dev_f, 2)      AS us_temp_dev_f,
  round(asia_precip, 1)        AS asia_precip,
  round(asia_drought, 2)       AS asia_drought,
  round(africa_precip, 1)      AS africa_precip,
  round(africa_flood, 2)       AS africa_flood,
  round(
    least(100.0, greatest(0.0,
      ((abs(us_precip) + abs(asia_precip) + abs(africa_precip)) / 3.0 / 60.0) * 100.0)),
    1)                         AS global_impact_index,
  round(
    least(100.0, greatest(0.0,
      ((asia_drought / 10.0) * 0.5 + (africa_flood / 10.0) * 0.3 + (pacific_convection / 100.0) * 0.2)
      * (0.55 + agri * 0.45) * 100.0)),
    1)                         AS agriculture_exposure
FROM base;
`;

const ANALOG_SQL = `
SELECT
  strftime(date, '%Y-%m')                                   AS period,
  nino_34_anomaly,
  nino34_sst,
  abs(nino_34_anomaly - CAST(? AS DOUBLE))                  AS delta,
  sst_deviation,
  precip_anomaly_pacific,
  precip_anomaly_us,
  precip_anomaly_se_asia,
  precip_anomaly_africa,
  drought_index_se_asia,
  risk_tier_pacific
FROM enso_historical
ORDER BY delta ASC, date DESC
LIMIT 6;
`;

const SUMMARY_SQL = `
SELECT
  count(*)                                              AS row_count,
  strftime(min(date), '%Y-%m')                          AS first_date,
  strftime(max(date), '%Y-%m')                          AS last_date,
  round(avg(nino_34_anomaly), 3)                        AS mean_anomaly,
  round(max(nino_34_anomaly), 3)                        AS max_anomaly,
  strftime(arg_max(date, nino_34_anomaly), '%Y-%m')     AS max_anomaly_date,
  count(*) FILTER (WHERE abs(nino_34_anomaly - CAST(? AS DOUBLE)) <= 0.35) AS analog_count,
  count(*) FILTER (WHERE nino_34_anomaly >= 2.0)        AS extreme_months,
  count(*) FILTER (WHERE nino_34_anomaly <= -0.5)       AS lanina_months,
  any_value(source)                                     AS source
FROM enso_historical;
`;

const TIMELINE_SQL = `
SELECT
  strftime(date, '%Y-%m')  AS date,
  nino_34_anomaly          AS anomaly
FROM enso_historical
ORDER BY date ASC;
`;

const RISK_TIER_SQL = `
WITH p AS (SELECT CAST(? AS DOUBLE) AS sst)
SELECT CASE
  WHEN sst < 0.5 THEN 'Neutral / La Niña Watch'
  WHEN sst < 1.0 THEN 'Weak Warm Phase'
  WHEN sst < 1.5 THEN 'Moderate El Niño'
  WHEN sst < 2.0 THEN 'Strong El Niño'
  WHEN sst < 2.6 THEN 'Super El Niño'
  ELSE 'Extreme Mega-El Niño'
END AS risk_tier
FROM p;
`;

// --- grid -------------------------------------------------------------------
// Each slider contributes min, max, midpoint AND quarter points. Crossing
// 7 x 5 x 6 = 210 combinations satisfies the ">= 200 points" requirement while
// still guaranteeing every documented boundary (0/3, -1/+1, 0/1) is covered —
// those are exactly where clamping and rounding diverge if the two
// implementations disagree.
const SST_GRID = [0, 0.5, 1.0, 1.5, 2.0, 2.5, 3];
const JET_GRID = [-1, -0.5, 0, 0.5, 1];
const AGRI_GRID = [0, 0.2, 0.4, 0.6, 0.8, 1];

// The three scenario points already used in earlier parity work.
const NAMED_POINTS = [
  [1.5, 0.35, 0.6],
  [0, 0, 0],
  [3, 1, 1],
];

function buildGrid() {
  const points = [];
  const seen = new Set();
  const push = (sst, jet, agri) => {
    const key = `${sst}|${jet}|${agri}`;
    if (seen.has(key)) return;
    seen.add(key);
    points.push({ sst, jet, agri });
  };

  for (const s of SST_GRID) for (const j of JET_GRID) for (const a of AGRI_GRID) push(s, j, a);
  for (const [s, j, a] of NAMED_POINTS) push(s, j, a);

  return points;
}

/** Arrow rows carry BigInt for counts; JSON cannot hold those. */
const toJsonable = (value) =>
  JSON.parse(
    JSON.stringify(value, (_k, v) => (typeof v === 'bigint' ? Number(v) : v)),
  );

async function main() {
  const blocking = require('@duckdb/duckdb-wasm/dist/duckdb-node-blocking.cjs');

  const csv = readFileSync(CSV_PATH, 'utf8');
  const tmpName = `enso-golden-${process.pid}.csv`;
  const tmpPath = path.join(root, tmpName);
  writeFileSync(tmpPath, csv);

  const logger = new blocking.ConsoleLogger(blocking.LogLevel.WARNING);
  // createDuckDB only constructs the bindings; instantiate() is what actually
  // loads the wasm module. Skipping it leaves the internal module null and the
  // first connect() throws "Cannot read properties of null (reading 'ccall')".
  const db = await blocking.createDuckDB(
    {
      mvp: {
        mainModule: require.resolve('@duckdb/duckdb-wasm/dist/duckdb-mvp.wasm'),
        mainWorker: null,
      },
    },
    logger,
    blocking.NODE_RUNTIME,
  );
  await db.instantiate();

  const conn = db.connect();

  // Mirror the app's post-connect hardening exactly.
  conn.query('SET autoinstall_known_extensions=false');
  conn.query('SET autoload_known_extensions=false');

  // Load the CSV via a registered buffer + read_csv(), NOT insertCSVFromPath.
  // The blocking Node bundle throws an Emscripten `_setThrew is not defined`
  // inside insertCSVFromPath's C++ import path; registering the text and letting
  // SQL parse it avoids that code path and matches how the browser engine loads
  // the identical bytes (registerFileText + read_csv).
  db.registerFileText('enso_golden.csv', csv);
  conn.query(`
    CREATE OR REPLACE TABLE enso_historical AS
    SELECT * FROM read_csv('enso_golden.csv', header=true, columns={
      'date': 'DATE', 'year': 'INTEGER', 'month': 'INTEGER',
      'nino12_sst': 'DOUBLE', 'nino12_anomaly': 'DOUBLE',
      'nino3_sst': 'DOUBLE', 'nino3_anomaly': 'DOUBLE',
      'nino4_sst': 'DOUBLE', 'nino4_anomaly': 'DOUBLE',
      'nino34_sst': 'DOUBLE', 'nino_34_anomaly': 'DOUBLE',
      'global_sst_anomaly': 'DOUBLE', 'sst_deviation': 'DOUBLE',
      'convection_shift': 'DOUBLE', 'precip_anomaly_pacific': 'DOUBLE',
      'precip_anomaly_us': 'DOUBLE', 'temp_deviation_us_f': 'DOUBLE',
      'precip_anomaly_se_asia': 'DOUBLE', 'drought_index_se_asia': 'DOUBLE',
      'precip_anomaly_africa': 'DOUBLE', 'flood_index_horn': 'DOUBLE',
      'agriculture_exposure': 'DOUBLE', 'risk_tier_pacific': 'VARCHAR',
      'source': 'VARCHAR', 'model_basis': 'VARCHAR'
    })
  `);

  const rowsOf = (table) => toJsonable(table.toArray().map((r) => r.toJSON()));

  // The blocking connection has no inline-parameter overload: `query(sql, ...)`
  // throws "Expected 3 parameters, but none were supplied". Binding goes through
  // a prepared statement, exactly like the browser engine's prepared path.
  const prepared = (sql, ...params) => {
    const stmt = conn.prepare(sql);
    try {
      return rowsOf(stmt.query(...params));
    } finally {
      stmt.close();
    }
  };

  const grid = buildGrid();
  const cases = [];

  for (const { sst, jet, agri } of grid) {
    cases.push({
      sst,
      jet,
      agri,
      metrics: prepared(SCENARIO_SQL, sst, jet, agri)[0],
      riskTier: prepared(RISK_TIER_SQL, sst)[0].risk_tier,
      summary: prepared(SUMMARY_SQL, sst)[0],
      analogs: prepared(ANALOG_SQL, sst),
    });
  }

  const timeline = rowsOf(conn.query(TIMELINE_SQL));

  const fixture = {
    meta: {
      generatedBy: 'scripts/gen-engine-golden.mjs',
      duckdbVersion: blocking.PACKAGE_VERSION,
      source: 'public/data/enso.csv',
      generatedAt: new Date().toISOString(),
      caseCount: cases.length,
      timelineRows: timeline.length,
      note: 'Produced by DuckDB from the same SQL the app runs. TsEngine must match within 1e-9 relative tolerance; strings, dates and ordering must match exactly.',
    },
    timeline,
    cases,
  };

  mkdirSync(path.dirname(OUT_PATH), { recursive: true });
  writeFileSync(OUT_PATH, `${JSON.stringify(fixture, null, 2)}\n`);

  conn.close();
  db.close?.();
  // Clean up the temp CSV even if a later step throws.
  try {
    readFileSync(tmpPath);
    const { unlinkSync } = require('node:fs');
    unlinkSync(tmpPath);
  } catch {
    /* already gone */
  }

  console.log(
    `wrote ${path.relative(root, OUT_PATH)} — ${cases.length} cases, ${timeline.length} timeline rows (duckdb ${blocking.PACKAGE_VERSION})`,
  );
}

main().catch((error) => {
  console.error('golden generation failed:', error);
  process.exit(1);
});
